import { describe, expect, it } from 'vitest';
import { addReleaseSigning } from './release-signing';

// Excerpt of android/app/build.gradle as generated by `expo prebuild` (SDK 57).
const TEMPLATE = `android {
    signingConfigs {
        debug {
            storeFile file('debug.keystore')
            storePassword 'android'
            keyAlias 'androiddebugkey'
            keyPassword 'android'
        }
    }
    buildTypes {
        debug {
            signingConfig signingConfigs.debug
        }
        release {
            // Caution! In production, you need to generate your own keystore file.
            // see https://reactnative.dev/docs/signed-apk-android.
            signingConfig signingConfigs.debug
            minifyEnabled enableMinifyInReleaseBuilds
        }
    }
}`;

describe('addReleaseSigning', () => {
  const result = addReleaseSigning(TEMPLATE);

  it('adds a release signing config fed from the environment', () => {
    expect(result).toMatch(/signingConfigs \{\s+\/\/ sem: release signing\s+release \{/);
    for (const name of [
      'ANDROID_KEYSTORE_PATH',
      'ANDROID_KEYSTORE_PASSWORD',
      'ANDROID_KEY_ALIAS',
      'ANDROID_KEY_PASSWORD',
    ]) {
      expect(result).toContain(`System.getenv('${name}')`);
    }
  });

  it('switches only the release build type to the release key', () => {
    expect(result).toContain(
      "signingConfig System.getenv('ANDROID_KEYSTORE_PATH') ? signingConfigs.release : signingConfigs.debug",
    );
    expect(result).toMatch(/debug \{\s+signingConfig signingConfigs\.debug\s+\}/);
    expect(result.match(/signingConfig signingConfigs\.debug\n/g)).toHaveLength(1);
  });

  it('keeps the debug signing config', () => {
    expect(result).toContain("storeFile file('debug.keystore')");
  });

  it('is idempotent', () => {
    expect(addReleaseSigning(result)).toBe(result);
  });

  it('fails loudly when the template changes', () => {
    expect(() => addReleaseSigning('android {}')).toThrow(/no signingConfigs block/);
    expect(() =>
      addReleaseSigning(TEMPLATE.replace(/release \{[\s\S]*?minifyEnabled/, 'release { minify')),
    ).toThrow(/release build type/);
  });
});
